import { format as originalFormat, FormatFn } from '../src/sqlFormatter.js';

describe('pipe extra', () => {
  const format: FormatFn = (query, cfg = {}) => originalFormat(query, { ...cfg, language: 'bigquery' });

  it('with cte', () => {
    const result = format(`WITH cte AS (FROM t |> SELECT a) SELECT * FROM cte`);
    console.log('CTE:\n' + result);
  });
  it('where with subquery', () => {
    const result = format(`FROM t |> WHERE a IN (SELECT b FROM u)`);
    console.log('SUBQ:\n' + result);
  });
  it('newlineBeforeSemicolon', () => {
    const result = format(`FROM t |> SELECT a`, { newlineBeforeSemicolon: true });
    console.log('NLSEMI:\n' + result);
  });
  it('block comment between pipe and kw', () => {
    const result = format(`FROM t |> /* c */ WHERE a > 1`);
    console.log('BLOCKPIPE:\n' + result);
  });
});
EOF
# copy into test dir to run with jest
cp /tmp/pipe_more2.test.ts test/pipe_more2.test.ts
npx jest test/pipe_more2.test.ts --coverage=false 2>&1 | sed -n '1,80p'
rm -f test/pipe_more2.test.ts

