cd /app && cat > /tmp/token_check.test.ts <<'EOF'
import { TokenType } from '../src/lexer/token.js';
import { bigquery } from '../src/languages/bigquery/bigquery.formatter.js';
import { createDialect } from '../src/dialect.js';

test('pipe token', () => {
  const dialect = createDialect(bigquery);
  const tokens = dialect.tokenizer.tokenize(`FROM t |> WHERE a > 1`, {});
  console.log(tokens.map(t => [t.type, t.text]).filter(([, text]) => text === '|>' || text === '|' || text === '>'));
  const pipe = tokens.find(t => t.text === '|>');
  expect(pipe?.type).toBe(TokenType.PIPE);
});
EOF
