actions.command:
cd /app && cat > test/pipe_setop.test.ts <<'EOF'
import dedent from 'dedent-js';
import { format as originalFormat, FormatFn } from '../src/sqlFormatter.js';

describe('setop after pipe', () => {
  const format: FormatFn = (q, c = {}) => originalFormat(q, { ...c, language: 'bigquery' });

  it('traditional set op still works', () => {
    const r = format(`SELECT * FROM foo UNION ALL SELECT * FROM bar;`);
    console.log('TRAD:\n' + r);
    expect(r).toBe(dedent`
      SELECT
        *
      FROM
        foo
      UNION ALL
      SELECT
        *
      FROM
        bar;
    `);
  });

  it('chained set op', () => {
    const r = format(`SELECT a FROM t1 UNION ALL SELECT b FROM t2 UNION ALL SELECT c FROM t3`);
    console.log('CHAIN:\n' + r);
  });

  it('pipe then set op', () => {
    const r = format(`FROM t |> SELECT a UNION ALL SELECT b FROM u`);
    console.log('PIPESET:\n' + r);
  });

  it('set op then pipe', () => {
    const r = format(`SELECT a FROM t UNION ALL FROM u |> SELECT b`);
    console.log('SETPIPE:\n' + r);
  });

  it('pipe basic still works', () => {
    const r = format(`FROM t |> WHERE a > 1 |> SELECT a`);
    console.log('BASIC:\n' + r);
  });
});
EOF
npx jest test/pipe_setop.test.ts --coverage=false 2>&1 | sed -n '1,120p'

